#!/usr/bin/env bash
set -euo pipefail

REMOTE_DIR="$1"
TELEGRAM_BOT_TOKEN="$2"
ACCESS_PASSPHRASE="${3:-}"
OPENROUTER_API_KEY="${4:-}"
OPENROUTER_MODEL="${5:-openai/gpt-4o-mini}"
OPENROUTER_AUDIO_MODEL="${6:-google/gemini-2.0-flash-001}"
GROQ_API_KEY="${7:-}"
GROQ_WHISPER_MODEL="${8:-whisper-large-v3-turbo}"
DEFAULT_TIMEZONE="${9:-Asia/Kuala_Lumpur}"
DEFAULT_MORNING_BRIEF="${10:-08:00}"
DEFAULT_EVENING_PULSE="${11:-21:00}"
WEBAPP_PORT="${12:-8040}"
MINI_APP_URL="${13:-}"

mkdir -p "$REMOTE_DIR/data"
cd "$REMOTE_DIR"

cat > .env <<EOF
# Auto-generated by deploy/sync.bat
APP_ENV=production
HOST=0.0.0.0
PORT=8000
WEBAPP_PORT=${WEBAPP_PORT}
MINI_APP_URL=${MINI_APP_URL}

# --- Security: Bot & Mini App Access Passphrase / PIN ---
ACCESS_PASSPHRASE=${ACCESS_PASSPHRASE}

# --- SQLite WAL Database (Persisted in ./data/cadence.db) ---
DATABASE_URL=sqlite+aiosqlite:///./data/cadence.db

# --- Telegram Bot ---
TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}
TELEGRAM_USE_WEBHOOK=false
TELEGRAM_WEBHOOK_URL=

# --- AI & Voice APIs ---
OPENROUTER_API_KEY=${OPENROUTER_API_KEY}
OPENROUTER_BASE_URL=https://openrouter.ai/api/v1
OPENROUTER_MODEL=${OPENROUTER_MODEL}
OPENROUTER_AUDIO_MODEL=${OPENROUTER_AUDIO_MODEL}
GROQ_API_KEY=${GROQ_API_KEY}
GROQ_WHISPER_MODEL=${GROQ_WHISPER_MODEL}

# --- Default User Preferences ---
DEFAULT_TIMEZONE=${DEFAULT_TIMEZONE}
DEFAULT_MORNING_BRIEF=${DEFAULT_MORNING_BRIEF}
DEFAULT_EVENING_PULSE=${DEFAULT_EVENING_PULSE}
EOF

chmod 600 .env
